        balance_error = total_load + total_loss - total_gen
        balance_penalty = (Price_current * max(0, balance_error)) / 2

        dict_plot['P_DG_5'].append(new_gen_p)
        dict_plot['SOC_BSS_9'].append(self.SOC)
